FROM token_usage_detail
WHERE space_id = #{spaceId}
  AND call_time >= #{start}
  AND call_time < #{end}

SELECT COALESCE(SUM(output_tokens), 0)
FROM token_usage_detail
WHERE space_id = #{spaceId}
  AND call_time >= #{start}
  AND call_time < #{end}

SELECT COUNT(*) > 0
