WHERE space_id = #{spaceId}
  AND call_time >= #{start}
  AND call_time < #{end}
  AND input_tokens IS NULL

SELECT COUNT(*) > 0
FROM token_usage_detail
WHERE space_id = #{spaceId}
  AND call_time >= #{start}
  AND call_time < #{end}
  AND output_tokens IS NULL

SELECT COUNT(*) > 0
FROM token_usage_detail
WHERE space_id = #{spaceId}
  AND call_time >= #{start}
  AND call_time < #{end}
  AND input_tokens_estimated = 1

SELECT COUNT(*) > 0
